from PIL import Image
import numpy as np
im = Image.open('mol_0081.png').convert('L')
A = np.array(im); bin_=(A<128).astype(np.uint8); H,W=bin_.shape

# refined vertices
V = {
 'a1':(350,700),'a2':(450,645),'a3':(560,700),'a4':(560,830),'a5':(450,880),'a6':(350,825),
 'b7':(655,520),'b8':(765,465),'b9':(875,520),'b10':(875,650),'b11':(765,705),'b12':(655,650),
 'b13':(765,830),'b14':(655,880),
 'c15':(975,465),'c16':(1080,525),'c17':(1080,650),'c18':(975,710),
 'd19':(975,350),'d20':(1085,295),'d21':(1195,355),'d22':(1190,480),
 'ipr':(880,295),
}
def density(p,q):
    p=np.array(p,dtype=float); q=np.array(q,dtype=float)
    n=int(np.linalg.norm(q-p)/2)+1
    cnt=0;tot=0
    for t in np.linspace(0.12,0.88,n):
        pt=p+(q-p)*t; x,y=int(round(pt[0])),int(round(pt[1]))
        x0,x1=max(0,x-3),min(W,x+4); y0,y1=max(0,y-3),min(H,y+4)
        tot+=1
        if bin_[y0:y1,x0:x1].mean()>0.22: cnt+=1
    return cnt/max(tot,1)

names=list(V.keys()); edges=[]
for i in range(len(names)):
    for j in range(i+1,len(names)):
        a,b=names[i],names[j]; pa,pb=V[a],V[b]
        d=np.hypot(pa[0]-pb[0],pa[1]-pb[1])
        if d<178:
            den=density(pa,pb)
            if den>0.40: edges.append((a,b,round(d),round(den,2)))
print("EDGES (density>0.4):")
for e in sorted(edges,key=lambda x:-x[3]): print(e)

# Build adjacency and find cycle basis
adj={n:set() for n in names}
for a,b,d,den in edges:
    if den>0.45:
        adj[a].add(b); adj[b].add(a)
print("\nAdjacency:")
for n in names: print(f"  {n} {V[n]}: {sorted(adj[n])}")
